import React from 'react';
import jackpot from "../assets/img/jack/jackpot.png";
import DiceNumber from './DiceNumber';

const Header = () => {
    
    return (
        <div 
            className="hidden lg:flex items-center h-[3.875rem] w-full bg-no-repeat bg-[length:100%_100%] scrollbar-hide"
            style={{ backgroundImage: `url(${jackpot})` }}
        >
            <DiceNumber number={4543} id={1} />
            <DiceNumber number={134} id={2} />
            <DiceNumber number={96999} id={3} />
        </div>
    );
};

export default Header;