import React, { useEffect, useState } from 'react';
import { useSelector } from 'react-redux';

const SplashScreen = ({ onFinish }) => {
  const { user } = useSelector((state) => state.auth);
  const [isVisible, setIsVisible] = useState(true);
  const [isDarkening, setIsDarkening] = useState(false);
  const [isBrightening, setIsBrightening] = useState(false);
  const [bgOpacity, setBgOpacity] = useState(0);

  useEffect(() => {
    const darkenTimer = setTimeout(() => {
      setIsDarkening(true);
      setBgOpacity(0.9);
    }, 100);

    const brightenTimer = setTimeout(() => {
      setIsBrightening(true);
      setBgOpacity(0);
    }, 1100);

    const finishTimer = setTimeout(() => {
      setIsVisible(false);
      if (onFinish) onFinish();
    }, 2000);

    return () => {
      clearTimeout(darkenTimer);
      clearTimeout(brightenTimer);
      clearTimeout(finishTimer);
    };
  }, [onFinish]);

  if (!isVisible) return null;

  return (
    <div className='fixed inset-0 w-full h-auto flex justify-center items-center z-50 overflow-hidden m-0 p-0 box-border'>
      <div
        className="absolute inset-0 bg-black"
        style={{
          opacity: bgOpacity,
          transition: 'opacity 1000ms ease-out',
        }}
      />
      
        <>
          <div className='w-[60%] z-10 font-["Impact",sans-serif] text-[28px] screen-6:text-[30px] screen-5:text-[38px] sm:text-[47px] md:text-[58px] screen-4:text-[75px] screen-3:text-[90px] screen-2:text-[102px] screen-1:text-[118px] text-splashTx text-center'>
            <p style={{
                opacity: isBrightening ? 0 : 1,
                transition: 'opacity 2500ms ease-out',
                willChange: 'opacity',
              }}>Welcome {user.username}!
                <br/>
                GOOD LUCK!!!
              </p>
          </div>
        </>
      
    </div>
  );
};

export default SplashScreen; 