import React, { useState, useEffect } from 'react';
import enFlag from '../assets/img/flag/en.png';
import esFlag from '../assets/img/flag/es.png';
import layoutImg from '../assets/img/temp/layout_8.png';
import wagerBox from '../assets/img/themes/wager_box.png';
import botBtnMain from '../assets/img/themes/botbutton_main.png';
import botBtnHover from '../assets/img/themes/botbutton_hover.png';
import botBtnDown from '../assets/img/themes/botbutton_down.png';
import lvlBg from '../assets/img/themes/lvl_bg.png';
import lvlProgress from '../assets/img/themes/lvl_progress.png';
import { useDispatch, useSelector } from 'react-redux';
import { Logout } from '../store/reducers/auth';
import { useNavigate } from 'react-router-dom';
import clickSound from '../assets/sounds/themes/vegasxwinter/click.mp3';
import '../assets/css/mobileHorizon.css';
import Pagination from './Pagination';

const Footer = () => {
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const { user } = useSelector((store) => store.auth);
    const [imgHeight, setImgHeight] = useState(40);
    const [logoutHovered, setLogoutHovered] = useState(false);
    const [helpHovered, setHelpHovered] = useState(false);
    const [logoutClicked, setLogoutClicked] = useState(false);
    const [helpClicked, setHelpClicked] = useState(false);
    const [currentTime, setCurrentTime] = useState('');
    const { gamePlayed } = useSelector((state) => state.games);

    const logout = () => {
        dispatch(Logout());
        navigate('/login')
    }

    const playClickSound = () => {
        const audio = new Audio(clickSound);
        audio.play();
    }

    useEffect(() => {
        const updateTime = () => {
            const now = new Date();
            const hours = now.getHours().toString().padStart(2, '0');
            const minutes = now.getMinutes().toString().padStart(2, '0');
            setCurrentTime(`${hours}:${minutes}`);
        };

        updateTime();
        const interval = setInterval(updateTime, 1000);

        return () => clearInterval(interval);
    }, []);

    const handleClick = () => {
        setImgHeight(50);
    };

    const handleMouseLeave = () => {
        setImgHeight(40);
    };

    const handleLogoutMouseDown = () => {
        setLogoutClicked(true);
    };

    const handleLogoutMouseUp = () => {
        setLogoutClicked(false);
    };

    const handleHelpMouseDown = () => {
        setHelpClicked(true);
    };

    const handleHelpMouseUp = () => {
        setHelpClicked(false);
    };

    return (
        !gamePlayed ? (
            <footer className='hidden regular-footer md:flex absolute bottom-0 left-0 right-0 z-[100] w-full'>
                <div className="flex flex-col pt-2 pr-2 w-[21.5%] text-white font-bold relative before:absolute before:inset-0 before:rounded-tr-[15px] before:bg-gradient-to-r before:from-[#6921bc] before:via-[#e8b3ff] before:via-[30%] before:to-[#943bf8] before:-z-10">
                    <div className="flex flex-col pb-[8px] items-center justify-end w-[99%] h-[125px] rounded-tr-[15px] text-white font-bold relative bg-[#601eae] shadow-[inset_0_0_10px_rgba(0,0,0,0.5)] shadow-[inset_0_0_10px_rgb(0 0 0 / 100%)]">
                        <div className='flex w-full h-[53.7px] items-center justify-center'>
                            <div className='flex flex-col w-[66.5%] cursor-pointer items-center justify-center h-full'>
                                <span className='text-[27px] lg:text-[33px] screen-3:text-[35px] screen-2:text-[38px] screen-1:text-[40px] text-cashbackFt font-normal font-["Impact"] screen-3:tracking-[0.1rem] screen-2:tracking-[0.3rem] screen-1:tracking-[0.5rem] drop-shadow-[2px_2px_3px_rgba(0,0,0,1)]'>BALANCE</span>
                            </div>
                            <div className='flex w-[33.5%] justify-between h-full'>
                                <button onClick={() => { handleClick(); playClickSound(); }} onMouseLeave={handleMouseLeave}><img src={enFlag} alt="English" className={`cursor-pointer w-[25px] h-[25px] lg:w-[30px] lg:h-[30px] screen-3:w-[40px] screen-3:h-[${imgHeight}px] rounded-full`} /></button>
                                <button onClick={() => { handleClick(); playClickSound(); }}><img src={layoutImg} alt="Layout" className='cursor-pointer w-[25px] h-[25px] lg:w-[30px] lg:h-[30px] screen-3:w-[40px] screen-3:h-[40px]' /></button>
                            </div>
                        </div>

                        <div className='flex w-full h-[68.7px] mr-[2px] shadow-[0_0_5px_rgba(0,0,0,0.6)] shadow-[0_0_5px_rgb(0 0 0 / 1)]'>
                            <div className='flex flex-col w-[66.5%] cursor-pointer items-center justify-center'>
                                <span className='text-[25px] screen-3:text-[35px] screen-2:text-[38px] screen-1:text-[40px] font-normal font-["Impact"] tracking-[0.2rem]' style={{ textShadow: '2px 2px 3px rgba(0,0,0,1)' }}>{(user?.balance * 100).toFixed(0)}</span>
                            </div>
                            <div className='flex w-[33.5%] h-full flex-col justify-center bg-cashbackBg rounded-[4px]'>
                                <p className="text-[9px] screen-2:text-[13px] screen-1:text-[15px] text-center text-cashbacktx font-normal font-impact cursor-pointer" style={{ textShadow: '2px 2px 3px rgba(0,0,0,1)' }}>CASHBACK BONUS</p>
                                <p className="text-[18px] screen-3:text-[20px] screen-2:text-[23px] screen-1:text-[25px] text-center font-normal font-impact cursor-pointer" style={{ textShadow: '2px 2px 3px rgba(0,0,0,1)' }}>1560</p>
                            </div>
                        </div>
                    </div>
                </div>

                <div className="flex flex-col w-[57%]">
                    <Pagination />
                    
                    <div className='flex w-full'>
                        <div className='flex justify-center items-center ml-[1.04%] mr-[2.96%] w-[52%] h-[5.75rem] self-end' style={{ backgroundImage: `url(${wagerBox})`, backgroundSize: '100% 100%', backgroundPosition: 'center', backgroundRepeat: 'no-repeat' }}>
                            <p className="text-center text-white text-[10px] lg:text-[13px] screen-3:text-[15px] screen-2:text-[18px] screen-1:text-[20px] font-['Impact'] leading-[1.1] tracking-wider" style={{ textShadow: '2px 2px 3px rgba(0,0,0,1)', letterSpacing: '0.05em' }}>
                                BALANCE 8056 CHARGEABLE BALANCE 2028
                                <br />
                                WAGER GOOD CASHBACK BONUS 1560
                                <br />
                                DAILY BONUS 28
                            </p>
                        </div>

                        <div className='flex justify-center w-[48%] mr-[5%] items-center self-end'>
                            <button
                                className='w-full text-white text-[20px] lg:text-[26px] screen-3:text-[30px] screen-2:text-[33px] screen-1:text-[35px] font-["Impact"] tracking-[0.1em] h-[4.88rem] cursor-pointer'
                                style={{
                                    textShadow: '2px 2px 3px rgba(0,0,0,1)',
                                    backgroundImage: `url(${logoutClicked ? botBtnDown : (logoutHovered ? botBtnHover : botBtnMain)})`,
                                    backgroundSize: '100% 100%',
                                    backgroundPosition: 'center',
                                    backgroundRepeat: 'no-repeat'
                                }}
                                onMouseEnter={() => setLogoutHovered(true)}
                                onMouseLeave={() => {
                                    setLogoutHovered(false);
                                    setLogoutClicked(false);
                                }}
                                onMouseDown={handleLogoutMouseDown}
                                onMouseUp={handleLogoutMouseUp}
                                onClick={() => {
                                    playClickSound();
                                    logout();
                                }}
                            >
                                LOGOUT
                            </button>
                            <button
                                className='w-full text-white text-[20px] lg:text-[26px] screen-3:text-[30px] screen-2:text-[33px] screen-1:text-[35px] font-["Impact"] tracking-[0.1em] h-[4.88rem] cursor-pointer'
                                style={{
                                    textShadow: '2px 2px 3px rgba(0,0,0,1)',
                                    backgroundImage: `url(${helpClicked ? botBtnDown : (helpHovered ? botBtnHover : botBtnMain)})`,
                                    backgroundSize: '100% 100%',
                                    backgroundPosition: 'center',
                                    backgroundRepeat: 'no-repeat'
                                }}
                                onMouseEnter={() => setHelpHovered(true)}
                                onMouseLeave={() => {
                                    setHelpHovered(false);
                                    setHelpClicked(false);
                                }}
                                onMouseDown={handleHelpMouseDown}
                                onMouseUp={handleHelpMouseUp}
                                onClick={() => {
                                    playClickSound();
                                }}
                            >
                                HELP
                            </button>
                        </div>
                    </div>
                </div>

                <div className="flex flex-col pt-2 pl-2 w-[21.5%] text-white font-bold relative before:absolute before:inset-0 before:rounded-tl-[15px] before:bg-gradient-to-l before:from-[#6921bc] before:via-[#e8b3ff] before:via-[30%] before:to-[#943bf8] before:-z-10">
                    <div className="flex flex-col pb-[12px] items-end justify-end h-[125px] w-[99%] ml-auto rounded-tl-[15px] text-white font-bold relative bg-[#601eae] shadow-[inset_0_0_10px_rgba(0,0,0,0.5)] shadow-[inset_0_0_10px_rgb(0 0 0 / 100%)]">
                        <div className='pt-[8px] pb-[1rem] px-[10px] w-full'>
                            <div className="flex w-full items-center h-[44px]" style={{ backgroundImage: `url(${lvlBg})`, backgroundSize: '100% 100%', backgroundPosition: 'center', backgroundRepeat: 'no-repeat' }}>
                                <div className='relative flex py-[3px] w-[86.2%] h-[100%]'>
                                    <span className='absolute inset-0 flex items-center text-cashbackFt text-[30px] lg:text-[35px] screen2:text-[40px] mb-[3px] left-[30%] lg:left-[40%] font-["Impact"] tracking-[0.15em]' style={{ textShadow: '2px 2px 3px rgba(0,0,0,1)' }}>{user?.username}</span>
                                    <img src={lvlProgress} alt="Lvl Progress" className='pl-[2.5px] w-[25%] h-[100%]' />
                                </div>
                                <div className='flex items-center justify-center w-[12.8%] h-[100%]'>
                                    <p className='text-right text-searchTx text-[21px] screen-3:text-[23px] screen-2:text-[26px] screen-1:text-[28px] font-["Impact"]' style={{ textShadow: '2px 2px 3px rgba(0,0,0,1)' }}>3</p>
                                </div>
                            </div>
                        </div>
                        <div className='flex w-full h-[46px] ml-[3px] shadow-[0_0_5px_rgba(0,0,0,0.3)] shadow-[0_0_5px_rgb(0 0 0 / 1)]'>
                            <div className='flex pl-[15px] lg:pl-[30px] w-[50%] h-full items-center'>
                                <p className='text-[20px] lg:text-[23px] screen-3:text-[25px] screen-2:text-[28px] screen-1:text-[30px] text-cashbackFt font-["Impact"] tracking-[0.15em]' style={{ textShadow: '2px 2px 3px rgba(0,0,0,1)' }}>{currentTime}</p>
                            </div>
                            <div className='flex w-[50%] h-full items-center'>
                                <p className='text-[20px] lg:text-[28px] screen-3:text-[30px] screen-2:text-[33px] screen-1:text-[35px] font-["Impact"] tracking-[0.15em]' style={{ textShadow: '2px 2px 3px rgba(0,0,0,1)' }}>Find...</p>
                            </div>
                        </div>
                    </div>
                </div>
            </footer>
        ) : null
    );
};

export default Footer;
